h", "auto_failure_mechanism": "B_powered_null (adequately powered null result)", "observed_failure_evidence": "among 653 eligible, corr(D_A, dPPP_allowed)=+0.020; high-D_A names (Isaiah Joe 0.168, Trey Lyles 0.157) often allow more PPP", "observed_sample_and_power": "n=653 eligible of 882", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_verdict": "null", "observed_failure_type": "B_powered_null"}, "relationships": [{"rel": "auto_has_risk", "node": "RISK:MECHANICAL_FLOOR"}, {"rel": "auto_related_family", "node": "FAM:SF-PAP-014"}]}, {"id": "FAM:SF-APPA-030", "label": "Study family SF-APPA-030: Play-type label backfill verification", "score": 0.381, "reached_via": ["FAM:SF-APPA-005 auto_related_family (limitation_precedent) FAM:SF-APPA-030"], "attributes": {"observed_research_question": "Play-type label backfill verification", "auto_outcome_status": "inconclusive", "observed_hypothesis": "Backfilled play-type labels match expected league distributions and team identities.", "observed_result": "PNR 28.7% FAIL (band 20-28%); PULL_UP 7.9% FAIL; 3100 games with team PNR >33% FAIL; PNR PPP 0.948 PASS; temporal PASS; team identity FAIL; 2024-25 PULL_UP ~0-1% for many teams. Final: FAIL.", "auto_failure_mechanism": "C_artifact (apparent effect produced by a construction, selection or labelling flaw)", "observed_failure_evidence": "2024-25 PULL_UP shares 0.0-2.0% for many teams; 82.8% of PNR labels proxy_calibrated.", "observed_sample_and_power": "921,514 possessions", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:label_or_classification_error"}, {"rel": "auto_has_risk", "node": "RISK:LABEL_ERROR"}, {"rel": "auto_related_family", "node": "FAM:SF-APPA-001"}, {"rel": "auto_related_family", "node": "FAM:SF-APPA-005"}]}, {"id": "FAM:SF-CHT-032", "label": "Study family SF-CHT-032: Teammate DRIVE then PNR including calibrated labels then inferrer-only", "s